/**
 * Practice builder for Topic 4: Tutorial 5 (35 parts) and APP PRACTICE for
 * §4.3.1 critical points (4 items).
 *
 * Tutorial 5 has no answer key, so every walkthrough is generated by the app
 * from authored working and labelled: hints as APP GUIDANCE, the full
 * walkthrough and answer as APP-GENERATED SOLUTION, status
 * pendingLecturerReview. Every authored derivative, value, plane, line,
 * critical point and value of d is recorded in SUGGESTED and verified
 * independently by the tests (so a wrong suggestion fails the build); the
 * learner's answers are checked from the question itself
 * (lib/math/partial.ts and lib/math/applications.ts), never from a typed key.
 */
import type { PracticeItem, PracticeModeId, WorkedStep } from '../../types';
import type { ExtremaSpec, PointType, SurfaceSpec } from '@/lib/math/applications';
import { evaluate } from '@/lib/math/input/evaluate';
import { parseStatement } from '@/lib/math/input/parse';
import { statementToTex } from '@/lib/math/input/toTex';
import type { PartialSpec, PartialTarget, Point } from '@/lib/math/partial';

import { PDA_TOPIC_ID, type PdaUnitId } from './ids';
import { PDA_MANUAL_REVIEW } from './manualReview';

export const PDA_TECHNIQUES = {
  'pda-total-differential': 'Review from §3.3: Total Differential and Gradient Components',
  'pda-gradient': 'The gradient at a point',
  'pda-tangent-plane': 'Tangent planes',
  'pda-normal-line': 'Tangent planes and normal lines',
  'pda-critical-points': 'Finding critical points',
  'pda-second-partials': 'Classifying critical points: the Second Partials Test',
} as const;

export type PdaTechnique = keyof typeof PDA_TECHNIQUES;

