const NEXT_ACTIONS: Record<PdaTechnique, string> = {
  'pda-total-differential': 'Find each first partial derivative.',
  'pda-gradient': 'Find each first partial derivative, then substitute the point.',
  'pda-tangent-plane': 'Write the surface as $F(x, y, z) = 0$ and find $F_{x}$, $F_{y}$ and $F_{z}$.',
  'pda-normal-line': 'Find $\\nabla F$ at the point: its components are the direction numbers of the normal line.',
  'pda-critical-points': 'Find $f_{x}$ and $f_{y}$, set both equal to 0, and solve them together.',
  'pda-second-partials': 'Find all the critical points first, then $f_{xx}$, $f_{yy}$ and $f_{xy}$.',
};

const MODE_FOR_DIFFICULTY: Record<1 | 2 | 3, PracticeModeId> = { 1: 'guided', 2: 'independent', 3: 'challenge' };

/** Generic sample points (inside most domains). */
