/** TeX of a learner-syntax expression or equation (e.g. "-6(x - 3) - (z - 15) = 0"). */
export const tex = (learner: string): string => statementToTex(parseStatement(learner));

interface SpecBase {
  instruction: string;
  /** The question's formula, as printed (TeX). */
  problem: string;
  technique: PdaTechnique;
  difficulty: 1 | 2 | 3;
  /** One sentence of method (the second hint). */
  method: string;
  reviewIds?: string[];
}

/** Gradient at a point (§4.1) or total differential coefficients (§3.3 review): the Topic 3 checker. */
export interface DerivativeSpec extends SpecBase {
  kind: 'derivatives';
  partial: PartialSpec;
  /** Name and variables in TeX for the walkthrough, e.g. "h" or "z". */
  name: string;
  /** Each first partial derivative, in learner syntax (verified in the tests). */
  derivatives: string[];
  /** Suggested answers, one per target, in learner syntax (accepted by the checker in the tests). */
  answers: string[];
  /** Labels of the targets in TeX. */
  labelsTex: string[];
  /** The point in TeX (gradient at a point only). */
  pointTex?: string;
  /** Final result in TeX. */
  answerTex: string;
}

/** Tangent plane (and normal line) to F(x, y, z) = 0 at P (§4.2.1). */
export interface SurfaceItemSpec extends SpecBase {
  kind: 'surface';
  surface: SurfaceSpec;
  /** F(x, y, z) in TeX. */
  Ftex: string;
  /** A sentence explaining how F was formed (e.g. "with F = f(x, y) − z"). */
  Fnote: string;
  /** F_x, F_y, F_z in learner syntax (verified). */
  partials: [string, string, string];
  /** Their exact values at P (verified). */
  values: [string, string, string];
  /** P in TeX. */
  pointTex: string;
  /** Theorem 4.2.2 with the values substituted, in learner syntax (verified to be the plane). */
  substituted: string;
  /** The simplified plane, in learner syntax (accepted by the checker). */
  plane: string;
  /** The normal line as symmetric equations, in learner syntax (accepted by the checker). */
  line?: string;
}

export interface ExtremaPointWork {
  x: string;
  y: string;
  type?: PointType;
  /** f_xx at the point, exact (verified). */
  fxx?: string;
  /** d at the point, exact (verified). */
  d?: string;
}

/** Critical points (§4.3.1), classified by the Second Partials Test when `classify`. */
export interface ExtremaItemSpec extends SpecBase {
  kind: 'extrema';
  f: string;
  classify: boolean;
  /** f_x and f_y in learner syntax (verified). */
  fx: string;
  fy: string;
  /** How the system f_x = 0, f_y = 0 is solved, in words with $…$ maths (app guidance). */
  solve: string;
  /** f_xx, f_yy, f_xy in learner syntax (verified), when classifying. */
  second?: [string, string, string];
  points: ExtremaPointWork[];
}

/** A question answered in writing (not auto-graded); no app solution while it awaits lecturer guidance. */
export interface WrittenSpec extends SpecBase {
  kind: 'written';
  /** Derivatives for checking lines of working only. */
  partial: PartialSpec;
}

export type PdaPracticeSpec = DerivativeSpec | SurfaceItemSpec | ExtremaItemSpec | WrittenSpec;

const TYPE_TEX: Record<PointType, string> = {
  min: '\\text{relative minimum}',
  max: '\\text{relative maximum}',
  saddle: '\\text{saddle point}',
  inconclusive: '\\text{test inconclusive}',
};
const TYPE_WORDS: Record<PointType, string> = {
  min: 'a relative minimum',
  max: 'a relative maximum',
  saddle: 'a saddle point',
  inconclusive: 'inconclusive',
};

const pointTex = (x: string, y: string) => `(${tex(x)}, ${tex(y)})`;
const step = (explanation: string, t?: string): WorkedStep => (t ? { explanation, tex: t } : { explanation });

function stepsFor(spec: PdaPracticeSpec): { steps: WorkedStep[]; answerTex: string } {
  switch (spec.kind) {
    case 'derivatives': {
      const vars = spec.partial.variables;
      const derivs = spec.derivatives.map((d, i) => `${spec.name}_{${vars[i]}} = ${tex(d)}`).join(', \\quad ');
      if (spec.technique === 'pda-total-differential') {
        const terms = spec.derivatives.map((d, i) => `\\left(${tex(d)}\\right)d${vars[i]}`).join(' + ');
        return {
          steps: [
            step('Find each first partial derivative, holding the other variables constant:', derivs),
            step(`By §3.3, the total differential has one term for each variable:`, `d${spec.name} = ${terms}`),
            step(
              'The coefficients of the differentials are the first partial derivatives: the same components that form the gradient in §4.1.',
            ),
          ],
          answerTex: spec.answerTex,
        };
      }
      const values = spec.answers.map((a, i) => `${spec.labelsTex[i]} = ${tex(a)}`).join(', \\quad ');
      return {
        steps: [
          step('Find each first partial derivative:', derivs),
          step(`Evaluate them at the point $${spec.pointTex ?? ''}$:`, values),
          step('By §4.1, the gradient is the vector of these components:', spec.answerTex),
        ],
        answerTex: spec.answerTex,
      };
    }
    case 'surface': {
      const [fx, fy, fz] = spec.partials;
      const [a, b, c] = spec.values;
      const steps: WorkedStep[] = [
        step(`Write the surface as $F(x, y, z) = 0$, ${spec.Fnote}:`, `F(x, y, z) = ${spec.Ftex}`),
        step(
          'Find the partial derivatives of $F$:',
          `F_{x} = ${tex(fx)}, \\quad F_{y} = ${tex(fy)}, \\quad F_{z} = ${tex(fz)}`,
        ),
        step(
          `Evaluate them at $${spec.pointTex}$:`,
          `F_{x} = ${tex(a)}, \\quad F_{y} = ${tex(b)}, \\quad F_{z} = ${tex(c)}`,
        ),
        step('Substitute into Theorem 4.2.2:', tex(spec.substituted)),
        step('Simplify:', tex(spec.plane)),
      ];
      if (spec.line) {
        steps.push(
          step(
            `The normal line goes through $${spec.pointTex}$ in the direction of $\\nabla F$ there (Theorem 4.2.1), so its direction numbers are $${tex(a)}$, $${tex(b)}$ and $${tex(c)}$ (or any nonzero multiple). Its symmetric equations are`,
            tex(spec.line),
          ),
        );
      }
      return {
        steps,
        answerTex: spec.line ? `${tex(spec.plane)}; \\quad ${tex(spec.line)}` : tex(spec.plane),
      };
    }
    case 'extrema': {
      const list = spec.points.map((p) => pointTex(p.x, p.y)).join(', \\; ');
      const steps: WorkedStep[] = [
        step('Find the first partial derivatives:', `f_{x} = ${tex(spec.fx)}, \\quad f_{y} = ${tex(spec.fy)}`),
        step(spec.solve, `\\text{Critical points: } ${list}`),
      ];
      if (spec.classify && spec.second) {
        const [xx, yy, xy] = spec.second;
        steps.push(
          step(
            'Find the second partial derivatives:',
            `f_{xx} = ${tex(xx)}, \\quad f_{yy} = ${tex(yy)}, \\quad f_{xy} = ${tex(xy)}`,
          ),
        );
        for (const p of spec.points) {
          const d = p.d ?? '0';
          const sign = evaluateNumber(d);
          const why =
            p.type === 'saddle'
              ? 'so by Theorem 4.3.3 it is a saddle point.'
              : p.type === 'inconclusive'
                ? 'so the test is inconclusive.'
                : `and $f_{xx} = ${tex(p.fxx ?? '0')}$ ${p.type === 'min' ? '> 0' : '< 0'}, so by Theorem 4.3.3 it is ${TYPE_WORDS[p.type ?? 'min']}.`;
          steps.push(
            step(`At $${pointTex(p.x, p.y)}$: $d = ${tex(d)}$ ${sign > 0 ? '> 0' : sign < 0 ? '< 0' : '= 0'}, ${why}`),
          );
        }
      }
      const answerTex = spec.classify
        ? spec.points.map((p) => `${pointTex(p.x, p.y)}\\; ${TYPE_TEX[p.type ?? 'min']}`).join(', \\; ')
        : list;
      return { steps, answerTex };
    }
    case 'written':
      return { steps: [], answerTex: '' };
  }
}

/** A plain number from a learner-syntax exact value, by the same safe evaluator (to word the sign of d). */
export function evaluateNumber(text: string): number {
  const statement = parseStatement(text);
  if (statement.k !== 'expr') return Number.NaN;
  return evaluate(statement.node, 0, { variable: 'x', constants: {}, definitions: {}, base: 0 }).v;
}

export function buildPdaItem(
  base: Pick<
    PracticeItem,
    'id' | 'sourceType' | 'source' | 'sourceQuestion' | 'sourceSubquestion' | 'sourceSection'
  > & { unitId: PdaUnitId },
  spec: PdaPracticeSpec,
): PracticeItem {
  const reviewIds = [...new Set(spec.reviewIds ?? [])];
  const known = new Set(PDA_MANUAL_REVIEW.map((m) => m.id));
  for (const id of reviewIds) if (!known.has(id)) throw new Error(`Unknown review item ${id}`);
  if (spec.kind === 'derivatives' && spec.answers.length !== spec.partial.targets.length) {
    throw new Error(`${base.id}: ${spec.answers.length} answers for ${spec.partial.targets.length} targets`);
  }
  const written = spec.kind === 'written';
  const { steps, answerTex } = stepsFor(spec);
  const checking =
    spec.kind === 'derivatives' || spec.kind === 'written'
      ? { partial: spec.partial }
      : spec.kind === 'surface'
        ? { surface: spec.surface }
        : {
            extrema: {
              f: spec.f,
              classify: spec.classify,
              points: spec.points.map((p) => ({ x: p.x, y: p.y, ...(p.type ? { type: p.type } : {}) })),
            } satisfies ExtremaSpec,
          };
  return {
    ...base,
    topicId: PDA_TOPIC_ID,
    instruction: spec.instruction,
    problemTex: spec.problem,
    technique: spec.technique,
    techniqueLabel: PDA_TECHNIQUES[spec.technique],
    difficulty: spec.difficulty,
    recommendedPracticeMode: MODE_FOR_DIFFICULTY[spec.difficulty],
    supportsHints: true,
    supportsStepValidation: true,
    needsManualReview: reviewIds.length > 0,
    reviewIds,
    // No Topic 4 question is withheld: Q5(m) is a written self-check question instead (MR4-10).
    withheldFromLearners: false,
    isExtension: false,
    check: { variable: 'x', points: [], constants: {} },
    ...checking,
    grading: written ? 'written' : 'auto',
    hints: [CONCEPTUAL_HINTS[spec.technique], spec.method, NEXT_ACTIONS[spec.technique]],
    // Q5(m): the app solution is withheld until the lecturer gives guidance (MR4-10).
    ...(written
      ? {}
      : {
          solution: {
            status: 'pendingLecturerReview' as const,
            method: spec.method,
            steps,
            answerTex,
            verification: 'numericDerivative' as const,
            appGenerated: true,
          },
        }),
  };
}

/** The authored working of every item (for the tests). */
export const SUGGESTED: Map<string, PdaPracticeSpec> = new Map();

/** Builds an item and records its spec for the tests. */
export function pdaItem(base: Parameters<typeof buildPdaItem>[0], spec: PdaPracticeSpec): PracticeItem {
  SUGGESTED.set(base.id, spec);
  return buildPdaItem(base, spec);
}

/** Shorthand targets. */
export const value = (label: string, f: string, wrt: string[], point: Point): PartialTarget => ({
  kind: 'value',
  label,
  f,
  wrt,
  at: point,
});
export const deriv = (label: string, f: string, ...wrt: string[]): PartialTarget => ({
  kind: 'derivative',
  label,
  f,
  wrt,
});
